    (p2 : bptr) (regb : Z) (p1 : bptr) (allocb : Z) : list block :=
  [(q4, va, 8); (q2, q, SZ_SPCI_IMPL); (q1, v, NEWSZ_SSVC); (p4, schedb, NEWSZ_SCH); (p3, cfgb, NEWSZ_CFG); (p2, regb, NEWSZ_REG); (p1, allocb, SZ_ALLOCIMPL)].

(* [comment removed for export] *)
Lemma NoDup_nth_neq : forall (l : list bptr) (i j : nat) x y,
  List.NoDup l -> nth_error l i = Some x -> nth_error l j = Some y -> i <> j -> x <> y.
Proof.
  intros l i j x y ND Hi Hj NE E. subst y. apply NE. eapply (proj1 (List.NoDup_nth_error _) ND); [| rewrite Hi, Hj; reflexivity].
  apply (proj1 (nth_error_Some l i)). rewrite Hi. discriminate.
Qed.

